SELECT
FBNumber,
FRWeight,
TotalCharges,
--IntPayableAmount,
--FBIntPayAmount,
TrueIntPayAmt,
--IntAllocPayAmount,
--TotalTripLegWeight,
--[Alloc. %],
--[Int Alloc. $],
--TRTripNumber,
--TotalTripLegCost,
ExtraCost,
SUM(ISNULL(EmptyLegDriverAlloc,0))+SUM(ISNULL(EmptyLegTrailerAlloc,0)) as TotalEmptyLegCost,
SUM(TotalActualCost) as Total,
TrueIntPayAmt+ISNULL(ExtraCost,0)+SUM(ISNULL(EmptyLegDriverAlloc,0))+SUM(ISNULL(EmptyLegTrailerAlloc,0))+SUM(ISNULL(TotalActualCost,0)) as TotalActualCost 

FROM
(
	SELECT
	FBNumber,
	--FRPieces,
	FRWeight,
	TotalCharges,
	--FBIntPayAmount,
	--IntAllocPayAmount,
	--[Alloc. %],
	--[Int Alloc. $],
	--TotalTripLegWeight,
	--SUM(TripTotalCost) as TripTotalCost,
	--TrueIntPayAmt+SUM(TripTotalCost) as TotalCost,
	ExtraCost,
	EmptyLegDriverCost/CountLegID as EmptyLegDriverAlloc,
	TrailerEmptyLegCost/CASE WHEN TrailerCount=0 THEN 1 ELSE TrailerCount END as EmptyLegTrailerAlloc,
	--SUM(ExtraCost) as ExtraCostAmt,
	--SUM(EmptyLegDriverCost/CountLegID) as EmptyLegDriverAlloc,
	--SUM(TrailerEmptyLegCost/TrailerCount) as EmptyLegTrailerAlloc,
	--SumEmptyLegCost,
	--CountTest,
	CASE
		WHEN IntPayableAmount=SUM(AllocIntPayable) THEN 0
		WHEN IntPayableAmount-SUM(AllocIntPayable)<0 THEN IntPayableAmount
		ELSE IntPayableAmount-SUM(AllocIntPayable)
	END as TrueIntPayAmt,
	IntPayableAmount,
	SUM(AllocIntPayable) as AllocIntPayable,
	SUM(TripTotalCost) as TotalActualCost
	--TotalTripLegCost,
	--TRTripNumber

	FROM 
	(
		SELECT 
		BillNumber as FBNumber,
		--CASE
		--	WHEN CHARINDEX('-',BillNumber)-1<0 THEN BillNumber
		--	ELSE LEFT(BillNumber,CHARINDEX('-',BillNumber)-1)
		--END as FBNumber,
		--SUM(Pieces) as FRPieces,
		--Pieces,
		SUM(Weight) as FRWeight,
		--TotalWeight,
		--Weight,
		--SubCost,
		--Cost,
		SUM(TotalCharges) as TotalCharges,
		--SumCharges,
		SUM(IntPayableAmount) as IntPayableAmount,
		FBIntPayAmount,
		--CAST(CASE
		--	WHEN SUM(IntPayableAmount)-ISNULL(AllocIntPayable,0)=0 THEN SUM(IntPayableAmount)
		--	ELSE SUM(IntPayableAmount)-ISNULL(AllocIntPayable,0) 
		--END as DECIMAL (18,2)) as TrueIntPayAmt, 
		--How do I handle FBs with the same INT cost on the Shipments table and ShipmentCarrierCost table?
		ISNULL(AllocIntPayable,0) as AllocIntPayable,
		--IntPayableAdjAmount,
		TRTripNumber,
		CASE
			WHEN SUM(IntPayableAmount)=AllocIntPayable THEN 0
			ELSE AllocIntPayable
		END as IntPayAmount,
		ISNULL(TotalTripLegCost,0) as TotalTripLegCost,
		ISNULL(TotalTripLeg0Cost,0) as TotalTripLeg0Cost,
		CASE
			WHEN CountLegID=0 THEN ISNULL(TotalTripLeg0Cost,0)
			ELSE (SUM(Weight)/CASE WHEN TotalTripECWeight=0 THEN 1 ELSE TotalTripECWeight END) * ISNULL(TotalTripLeg0Cost,0)
		END as ExtraCost,

		--ISNULL(TotalTripLegCost,0)
		--+
		--CASE 
		--	WHEN CountLegID=0 THEN ISNULL(TotalTripLeg0Cost,0)
		--	ELSE ISNULL(TotalTripLeg0Cost,0)/ISNULL(CountLegID,1)
		--END as TotalTripLegCost,
	
		CountLegID,
		CountEmptyFB,
		TotalTripLegWeight,
		TotalTripECWeight,
		TRLegSeq,
		--TRResID,
		--ISNULL(TotalTripLegCost,0) as NoWeightTrip, --Need to find a way to handle FB without weight. Where it doesnt need any allocated calc.

		SUM(Weight)/CASE WHEN TotalTripLegWeight=0 THEN 1 ELSE TotalTripLegWeight END as 'Alloc. %',
		SUM(Weight)/CASE WHEN TotalTripECWeight=0 THEN 1 ELSE TotalTripECWeight END as 'ECAlloc. %',
	
		ROUND(((SUM(Weight)/CASE WHEN TotalTripLegWeight=0 THEN 1 ELSE TotalTripLegWeight END) *
		CASE
			WHEN AllocIntPayable IS NOT NULL THEN ISNULL(AllocIntPayable,0)
			ELSE 0
		END),4) as 'Int Alloc. $',

		EmptyLegDriver,
		EmptyLegDriverCost,
		EmptyLegTrailerDriver,
		TrailerEmptyLegCost,
		TrailerCount,

		CASE 
			WHEN TotalTripLegWeight IS NULL THEN ISNULL(TotalTripLegCost,0)
			WHEN ISNULL(TotalTripLegWeight,0)=0 THEN ISNULL(TotalTripLegCost,0) + ISNULL(TotalTripLeg0Cost,0)
			ELSE
			ROUND((SUM(Weight)/TotalTripLegWeight) * ISNULL(TotalTripLegCost,0)
			--+
			--(SUM(Weight)/TotalTripLegWeight) *
			--CASE
			--	WHEN CountLegID=0 THEN ISNULL(TotalTripLeg0Cost,0)
			--	ELSE ISNULL(TotalTripLeg0Cost,0)/ISNULL(CountLegID,1)
			--END
			+
			ROUND(((SUM(Weight)/CASE WHEN TotalTripLegWeight=0 THEN 1 ELSE TotalTripLegWeight END) *
			CASE
				WHEN AllocIntPayable IS NOT NULL THEN ISNULL(AllocIntPayable,0)
				ELSE 0
			END),4),2)
		END as TripTotalCost


		FROM Shipments S LEFT JOIN
		--ShipmentDetails SD on S.BillNumber=SD. LEFT JOIN
		TripResources TR on ResID=BillNumber LEFT JOIN
		--(
		--	SELECT
		--	BillNumber as InfoBillNo,
		--	SUM(Weight) as TotalWeight,
		--	SUM(TotalCharges) as SumCharges
		--	FROM
		--	Shipments
		--	GROUP BY
		--	BillNumber
		--)TotalBase on BillNumber=InfoBillNo LEFT JOIN

		--*********Trip/Leg Subquery. Looks for Total Weight, Trip/Leg Cost across all trips with a Leg sequence.*********
		(
			SELECT 
			TripNumber as TRTripNumber,
			LegId as TRLegId,
			CASE
				WHEN DriverSeqNo IS NULL THEN LegSeqNo
				ELSE DriverSeqNo
			END as TRLegSeq,
			COUNT(ResID) as TRResID,
			CAST(SUM(Weight) as DECIMAL (19,4)) as TotalTripLegWeight,
			TotalTripLegCost,
			TripDriverCode
			FROM
			TripResources LEFT JOIN
			(
				SELECT
				LegID as DriverLegId,
				LegSequence as DriverSeqNo,
				SUM(TotalPayAmount) as TotalTripLegCost,
				DriverCode as TripDriverCode
				FROM
				DriverPay  
				WHERE
				LegSequence>0
				--and TripNumber=676864
				GROUP BY
				LegID,
				LegSequence,
				DriverCode
			)DPBase on DriverLegId=LegID LEFT JOIN

			(
				SELECT
				LegId as LegSumId,
				LegSequence as LegSeqNo
				FROM
				LegSummary
			)LegSeqBase on LegSumId=LegId LEFT JOIN

			(
				SELECT
				BillNumber,
				Weight
				FROM
				Shipments
				WHERE
				BillNumber NOT LIKE ('%-%')
			)SDBase on BillNumber=ResID

			WHERE
			ResType='F'
			--and ResID LIKE ('45C842261%')
			--and TripNumber=695331
			--and ResID NOT LIKE ('%-%')
			GROUP BY
			TripNumber,
			LegId,
			CASE
				WHEN DriverSeqNo IS NULL THEN LegSeqNo
				ELSE DriverSeqNo
			END,
			TotalTripLegCost,
			TripDriverCode
		)TRBase on TRTripNumber=TripNumber AND TRLegId=LegID LEFT JOIN

		--*********Zero Leg Sequence Subquery. Looks for Total Payment on Trips with NULL/0 Legs. Distributes Cost on 0 Leg Trips if there's more than one Leg in the Trip.*********
		(
			SELECT --DISTINCT
			TripNumber as TR0TripNumber,
			--ResID,
			LegID as TR0LegID,
			TotalTripLeg0Cost,
			COUNT(FreightBills) as CountLegID,
			SUM(TotalWeight) as TotalTripECWeight
			--FBillNumber
			--COUNT(FBillNumber) as FBCount

			FROM
			TripResources LEFT JOIN
			(
				SELECT DISTINCT
				TripNumber as DPTripNumber0,
				DriverCode as DriverPayDC0,
				--TotalPayAmount,
				SUM(TotalPayAmount) as TotalTripLeg0Cost
				FROM
				DriverPay
				WHERE
				LegSequence=0
				--and TripNumber IN (696958,676864)
				GROUP BY
				TripNumber,
				DriverCode
			)DPBase on DPTripNumber0=TripNumber AND ResID=DriverPayDC0 LEFT JOIN
			(
				SELECT DISTINCT
				CONCAT(TripNumber,'-',ResID) as TRTripLegNo,
				TripNumber as TRTripNumber,
				ResID as Driver,
				CASE
					WHEN CHARINDEX('-',FreightBills)-1<0 THEN FreightBills
					ELSE LEFT(FreightBills,CHARINDEX('-',FreightBills)-1)
				END as FreightBills,
				TotalWeight
				FROM
				TripResources LEFT JOIN
				(	
					SELECT DISTINCT
					--TripNumber as TNTest,
					--LegId as LITest,
					CONCAT(TripNumber,'-',LegId) as TNLITest,
					ResID as FreightBills
					FROM
					TripResources
					WHERE
					ResType='F'
					and ResID NOT LIKE ('%-%')
				)RTBase on TNLITest=CONCAT(TripNumber,'-',LegId) LEFT JOIN
				(
					SELECT
					BillNumber,
					CAST(SUM(Weight) as DECIMAL (19,4)) as TotalWeight
					FROM
					Shipments
					WHERE
					BillNumber NOT LIKE ('%-%')
					GROUP BY
					BillNumber
				)ECWeightBase on FreightBills=BillNumber

				WHERE
				ResType='D'
				and FreightBills IS NOT NULL
				--and TripNumber IN (696958,676864)
				--and LS.FreightNumber IS NOT NULL
			)DP1Base on TRTripLegNo=CONCAT(TripNumber,'-',ResID) --LEFT JOIN

			--(
			--	SELECT
			--	ResID as FBillNumber,
			--	LegID as FreightLegID
			--	FROM 
			--	TripResources 
			--	WHERE
			--	ResType='F' 
			--)Driver on FreightLegID=LegID 

			WHERE
			ResType='D'
			--and ResID='36L846718'
			--and TripNumber IN (696958,697954)
			GROUP BY
			TripNumber,
			LegId,
			--DriverCode,
			TotalTripLeg0Cost
		)TR0Base on TR0TripNumber=TripNumber AND TR0LegID=LegID LEFT JOIN

		--*********Total Interline Cost per Trip Subquery. Pulls the Total Interline Cost on a Trip and applies it to all shipments to use for alloc. calculation.*********
		(
			SELECT 
			IntTripNumber,
			TRBillNo as IntAllocBillNo,
			IntID,
			OrdIntLegId,
			InterLinerID,
			AllocIntPayable,
			LegSeqNo as IntLegSeqNo

			FROM
			(
				SELECT
				TripNumber as IntTripNumber,
				LegId as IntLegId,
				ResID as IntID,
				OrdIntLegId,
				InterLinerID,
				AllocIntPayable
				FROM 
				TripResources LEFT JOIN
					(
						SELECT
						LegId as OrdIntLegId,
						InterLinerID,
						SUM(TotalAmount) as AllocIntPayable
						FROM 
						OrderInterliner
						GROUP BY
						LegID,
						InterLinerID
					)OrdIntBase on OrdIntLegId=LegId AND ResID=InterLinerID 
				WHERE
				ResType='I' 
				and OrdIntLegId IS NOT NULL
				--and TripNumber IN (652858,695331,649491)
			)IntBase /*on IntTripNumber=TripNumber*/ LEFT JOIN

			(
				SELECT
				LegId as LegSumId,
				LegSequence as LegSeqNo
				FROM
				LegSummary
				--WHERE
				--TripNumber IN (652858,695331,649491)
			)LegSeqBase on LegSumId=OrdIntLegId
			LEFT JOIN
			(
				SELECT
				LegId as TRLegId,
				TripNumber as TRTripNo,
				ResId as TRBillNo
				FROM 
				TripResources
				WHERE
				ResType='F'
			)TRBase on TRLegId=IntLegId AND TRTripNo=IntTripNumber 
			--LEFT JOIN

			--(
			--	SELECT
			--	--s.BillNumber,
			--	TripNumber as CarrierTripNo,
			--	CarrierId,
			--	CONCAT(TripNumber,'-',CarrierId) as TripCarrierId,
			--	SUM(AdjustedAmount) as IntAllocPayAmount
			--	FROM
			--	TripResources LEFT JOIN
			--	Shipments S on ResId=BillNumber LEFT JOIN
			--	ShipmentCarrierCosts SCC on SCC.ShipmentID=S.ShipmentID
			--	--WHERE
			--	--s.BillNumber IN ('36L842039','36L842138','36L842159','36L842160','36L842265','36L842267','36L842303','36L842304','36L842305','36L842489')
			--	GROUP BY
			--	--s.BillNumber,
			--	TripNumber,
			--	CarrierId,
			--	CONCAT(TripNumber,'-',CarrierId)
			--)CarrierCostBase on TripCarrierId=CONCAT(TripNumber,'-',IntID)

			WHERE
			--BillNumber IN ('36L842039','36L842160','37B761563','41L769874')
			--and 
			--and ResID='41L769874'
			IntTripNumber IN (695331,652858) 
			--BillNumber IS NOT NULL
			and IntID IS NOT NULL
			--and BillNumber NOT LIKE ('%-%')
		)IntAllocFBBase on IntAllocBillNo=BillNumber and IntTripNumber=TRTripNumber and TRLegSeq=IntLegSeqNo LEFT JOIN

		--*********Total Interline Cost by Shipment. Looks at each FB to find Total Interline Cost. Helps identify shipment holding total Interline Cost.*********
		(
			SELECT DISTINCT
			BillNumber as IntBillNumber,
			IntID,
			--SUM(AdjustedAmount) as FBIntPayAmount
			SumAdjustedAmount as FBIntPayAmount

			FROM
			TripResources LEFT JOIN
			Shipments on ResId=BillNumber LEFT JOIN

			(
				SELECT DISTINCT
				TripNumber as IntTripNumber,
				ResID as IntID
				FROM 
				TripResources 
				WHERE
				ResType='I' 
			)IntBase on IntTripNumber=TripNumber LEFT JOIN
			(
				SELECT
				s.BillNumber as CarrierCostBill,
				CarrierId,
				SUM(AdjustedAmount) as SumAdjustedAmount
				FROM
				ShipmentCarrierCosts scc LEFT JOIN
				Shipments s on scc.ShipmentID=s.ShipmentID
				--Where
				--CarrierID='TKOLOG'
				--and ShipmentID='00000000-0000-0000-0000-00000011283F'
				GROUP BY
				s.BillNumber,
				CarrierID
			)CarrierCostBase on CarrierId=IntID and CarrierCostBill=BillNumber

			WHERE
			--BillNumber IN ('36L842039','36L842160','37B761563')
			--and ResID='41L769874'
			--and TripNumber=695331
			--and 
			IntID IS NOT NULL
			and BillNumber NOT LIKE ('%-%')

			--GROUP BY
			--BillNumber,
			--IntID
		)IntFBBase on IntBillNumber=BillNumber LEFT JOIN

		--*********Total Empty Leg Cost by Shipment. Pulls all shipments on the Trip by Driver and allocates across number of shipments on the trip by that driver.*********

		(
			SELECT 
			--LegID,
			--TripNumber,
			EmptyLegDriverTripNo,
			EmptyLegDriver,
			--TripLegNo,
			COUNT(FreightBills) as CountEmptyFB,
			--AllocCount,
			EmptyLegDriverCost
			--SumWeightFB

			FROM --TripResources LEFT JOIN

			(
				SELECT DISTINCT
				TripNumber as EmptyLegDriverTripNo,
				DriverCode as EmptyLegDriver,
				--LS.LegSequence as EmptyLeg,
				--1,
				--DriverPayTotal
				--SUM(1) as CountTest,
				--Countt,
				EmptyLegDriverCost
				FROM 
				LegSummary LEFT JOIN
				(
					SELECT DISTINCT
					TripNumber as DriverTripNo,
					LegSequence as DriverLegSeq,
					SUM(TotalPayAmount) as EmptyLegDriverCost
					--COUNT(1) as Countt
					FROM
					DriverPay
					--WHERE
					--TripNumber IN (678290,678437,678288)
					GROUP BY
					TripNumber,
					LegSequence
				)DriverBase on TripNumber=DriverTripNo AND LegSequence=DriverLegSeq
				WHERE
				FreightNumber IS NULL
				--and TripNumber IN (678290,678437,678288)
				--GROUP BY
				----LS.LegID,
				--TripNumber,
				--DriverCode,
				--DriverPayTotal
			)ELSBase /*on EmptyLegSummaryTripNo=TripNumber*/ LEFT JOIN

			(
				SELECT DISTINCT
				CONCAT(TR.TripNumber,'-',ResID) as TRTripLegNo,
				TripNumber as TRTripNumber,
				ResID as Driver,
				CASE
					WHEN CHARINDEX('-',FreightBills)-1<0 THEN FreightBills
					ELSE LEFT(FreightBills,CHARINDEX('-',FreightBills)-1)
				END as FreightBills
				FROM
				TripResources TR LEFT JOIN
				(	
					SELECT DISTINCT
					--TripNumber as TNTest,
					--LegId as LITest,
					CONCAT(TripNumber,'-',LegId) as TNLITest,
					ResID as FreightBills
					FROM
					TripResources
					WHERE
					ResType='F'
				)RTBase on TNLITest=CONCAT(TripNumber,'-',LegId)
				WHERE
				ResType='D'
				and FreightBills IS NOT NULL
				--and TripNumber IN (694998)
			)EmptyAllocFBBase on CONCAT(EmptyLegDriverTripNo,'-',EmptyLegDriver)=TRTripLegNo 


			WHERE
			EmptyLegDriverTripNo IS NOT NULL
			--and EmptyLegSummaryTripNo IN (678290,678288,678437)
			GROUP BY
			EmptyLegDriverTripNo,
			EmptyLegDriver,
			EmptyLegDriverCost
		)EmptyLegByDriver on TripDriverCode=EmptyLegDriver AND EmptyLegDriverTripNo=TripNumber LEFT JOIN

		--*********Total Empty Leg Cost by Shipment where the Empty Leg doesnt have FBs to allocate cost to by Driver. Allocates across number of shipments on the trip by Trailer on Empty Leg.*********

		(
			SELECT
			EmptyLegTrailerTripNo,
			EmptyLegTrailerDriver,
			TrailerEmptyLegCost,
			SUM(TrailerCount) as TrailerCount

			FROM
			(
				SELECT 
				EmptyLegTrailerTripNo,
				EmptyLegTrailerDriver,
				--DriverEmptyLegId,
				--DriverEmptyLegSeq,
				SUM(TrailerEmptyLegCost) as TrailerEmptyLegCost,
				--LegSummaryDriver,
				--TrailerId,
				--FBTrailerId,
				--FreightBills
				--SUM(
				CASE
					WHEN FreightBills IS NULL THEN 0
					ELSE 1
				END as TrailerCount

				FROM 
				(
					SELECT DISTINCT
					TripNumber as EmptyLegTrailerTripNo,
					DriverCode as EmptyLegTrailerDriver,
					DriverEmptyLegId,
					LegSequence as DriverEmptyLegSeq,
					TrailerEmptyLegCost 
					FROM 
					LegSummary LEFT JOIN
					(
						SELECT DISTINCT
						TripNumber as DriverTripNo,
						LegID as DriverEmptyLegId,
						SUM(TotalPayAmount) as TrailerEmptyLegCost
						--COUNT(1) as Countt
						FROM
						DriverPay
						--WHERE
						--TripNumber IN (143885)
						GROUP BY
						TripNumber,
						LegID
					)DriverBase on TripNumber=DriverTripNo AND LegID=DriverEmptyLegId
					WHERE
					FreightNumber IS NULL
					--and TripNumber IN (143885)
					and DriverCode IS NOT NULL
				)ELSBase LEFT JOIN

				(
					SELECT DISTINCT
					TripNumber as LegSummaryTripNo,
					DriverCode as LegSummaryDriver,
					LegSequence as LegSummaryLegSeq
					FROM
					LegSummary
					WHERE
					FreightNumber IS NOT NULL
					--and TripNumber IN (697902)
				)LSBase on LegSummaryTripNo=EmptyLegTrailerTripNo AND EmptyLegTrailerDriver=LegSummaryDriver LEFT JOIN

				(
					SELECT DISTINCT
					TripNumber as TrailerTripNumber,
					ResID as TrailerId,
					LegID as TrailerLegId
					FROM
					TripResources 
					WHERE
					ResType='R'
					--and TripNumber IN (678290,678288,678437)
				)EmptyAllocFBBase on EmptyLegTrailerTripNo=TrailerTripNumber AND DriverEmptyLegId=TrailerLegId LEFT JOIN
				(
					SELECT DISTINCT
					ResID as FBTrailerId,
					TripNumber as FBTripNo,
					FreightBills
					--SUM(
					--CASE
					--	WHEN FreightBills IS NULL THEN 0
					--	ELSE 1
					--END) as TrailerCount
					FROM
					TripResources LEFT JOIN
					(	
						SELECT 
						CONCAT(TripNumber,'-',LegId) as TNLINo,
						ResID as FreightBills
						FROM
						TripResources
						WHERE
						ResType='F'
						and ResID NOT LIKE ('%-%')
					)RTBase on TNLINo=CONCAT(TripNumber,'-',LegId)

					WHERE
					--TripNumber=143885
					-- and
					ResType='R'
					--GROUP BY
					--ResID,
					--TripNumber
				)CountAllocBase on EmptyLegTrailerTripNo=FBTripNo AND TrailerId=FBTrailerId --AND LegID<>TrailerLegId

				WHERE
				EmptyLegTrailerTripNo IS NOT NULL
				and LegSummaryDriver IS NULL
				--and EmptyLegTrailerTripNo IN (697902,475192,143885,403992)
				--152470

				GROUP BY
				EmptyLegTrailerTripNo,
				EmptyLegTrailerDriver,
				CASE
					WHEN FreightBills IS NULL THEN 0
					ELSE 1
				END
				)BASE

		GROUP BY
		EmptyLegTrailerTripNo,
		EmptyLegTrailerDriver,
		TrailerEmptyLegCost
		)EmptyLegByTrailer on EmptyLegTrailerTripNo=TripNumber --AND DriverEmptyLegSeq=TRLegSeq



		WHERE
		--S.BillNumber IN ('36L817747','41L769874','36T822440','36T822440-AA') --Need to account for leg 0. Currently overstating cost. DONE
		--S.BillNumber IN (/*'36L817747',*/'36L822353','36L822358','36L821723') --Need to figure out how to account for the cost on an empty leg. Empty leg was for a pickup, cost should be on subsequent FB DONE
		--S.BillNumber IN ('45C821595','46A822827') --No weight on the FB. Alloc calc not needed. Avoid divide by zero error. DONE
